class Cart {
  #items = [];
  constructor(discountStrategy = total => total) { this.discountStrategy = discountStrategy; }
  add(item) { this.#items.push({ ...item }); }
  total() { const subtotal = this.#items.reduce((s, i) => s + i.price * i.qty, 0); return this.discountStrategy(subtotal); }
}
const cart = new Cart(total => total * 0.9);
cart.add({ price: 100, qty: 2 });
console.log(cart.total());
